import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { RouterProvider, createBrowserRouter, createRoutesFromElements } from 'react-router-dom'
import { ColorSchemeScript, MantineProvider } from '@mantine/core'
import '@mantine/core/styles.css'
import { appRoutes } from './app'
import { appTheme } from './theme'
import { DialogProvider } from './lib/dialogs'
import './index.css'

const root = document.getElementById('root')
if (!root) throw new Error('root element missing')

// Data router (vs <BrowserRouter>) is required so `useBlocker` works
// in the editor — that's how we intercept in-app navigation when a
// doc has unsaved changes. Hard refresh / close-tab is still caught
// by the editor's `beforeunload` listener.
const router = createBrowserRouter(createRoutesFromElements(appRoutes()))

// ColorSchemeScript injects a small inline <script> that sets
// `data-mantine-color-scheme` on <html> before paint, so the page
// doesn't flash light then jump to dark.
createRoot(root).render(
  <StrictMode>
    <ColorSchemeScript defaultColorScheme="auto" />
    <MantineProvider theme={appTheme} defaultColorScheme="auto">
      <DialogProvider>
        <RouterProvider router={router} />
      </DialogProvider>
    </MantineProvider>
  </StrictMode>
)

content.content:
/*
 * Theme tokens follow the roadmapper surface system: a dark navy stack
 * with a sibling light variant, and a single blue accent. Mantine sets
 * `data-mantine-color-scheme` on <html>; our vars switch on that so the
 * editor / inline-styled bits track the toggle automatically.
 *
 * Shape scale and surface naming mirror roadmapper/frontend/app.css so
 * future components copy across cleanly.
 */

:root,
:root[data-mantine-color-scheme="dark"] {
  color-scheme: dark;
  --bg: #0f1117;
  --bg-surface: #1a1d27;
  --bg-elevated: #242836;
  --border: #353b50;

  --text: #f8fafc;
  --text-muted: #c8d2e0;
  --text-dim: #94a3b8;

  --accent: #3b82f6; /* blue-500, brighter in dark mode */

  --brand: #f38020; /* ctxlayer orange — matches the marketing site logo */

  --sidebar-w: 220px;
  --header-h: 56px;
  --radius: 6px;
  --radius-sm: 4px;
}

:root[data-mantine-color-scheme="light"] {
  color-scheme: light;
  --bg: #f1f5f9;
  --bg-surface: #ffffff;
  --bg-elevated: #f8fafc;
  --border: #cbd5e1;

  --text: #0f172a;
---
import { createTheme, type MantineColorsTuple } from '@mantine/core'

// Tailwind's `blue` ramp (50..900) → Mantine's 0..9 tuple. Picked over
// Mantine's default blue because the project memory specifies a
// "Royal" #2563eb primary (blue-600), and the roadmapper reference
// has a heavier saturated feel we want to mirror.
const blue: MantineColorsTuple = [
  '#eff6ff', // 50  → mantine index 0
  '#dbeafe', // 100 → 1
  '#bfdbfe', // 200 → 2
  '#93c5fd', // 300 → 3
  '#60a5fa', // 400 → 4
  '#3b82f6', // 500 → 5  (dark-mode primary)
  '#2563eb', // 600 → 6  (light-mode primary)
  '#1d4ed8', // 700 → 7
  '#1e40af', // 800 → 8
  '#1e3a8a' // 900 → 9
]

export const appTheme = createTheme({
  primaryColor: 'blue',
  primaryShade: { light: 6, dark: 5 },
  colors: { blue },
  fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
  defaultRadius: 'sm',
  radius: { xs: '2px', sm: '4px', md: '6px', lg: '8px', xl: '12px' },
  cursorType: 'pointer'
})

